PGM   code
Start
   movlb 0x0F ;sel bank F in BSR to access registers not in Access Bank. Only registers placed between 0xF60 and 0xFFF are mapped in the access bank
   clrf ANSELA,BANKED ;port A digital (note that ANSELA is located at H'0F38', outside the [0xF60,0xFFF] range)
