   clrf ANSELC,BANKED ;port C digital

   clrf ANSELD, BANKED ; port d digital
   movlw b'11000000'
   movwf TRISD
   
Loop

iff
   BTFSC PORTD, 6
   BTFSS PORTD, 7
   GOTO elsee
      BSF LATD, 5
      GOTO fi_if
elsee
      BCF LATD, 5
fi_if

   MOVLW d'16' ; 1c
   MOVWF counter ; 1c
   
bucle
   DECFSZ counter ; 1c (última iteració són 3c) 
   GOTO bucle ; 2c
   
   BTG LATD, 4
   
   goto Loop   
